using System;using System.Windows.Media.Media3D;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Windows.Forms;
namespace GearLab {
 // Служебная команда --variant-check <папка>: новые звенья получают корпус РОБОТ1, реальное CAD-ядро строит их и соседей.
 internal static class VariantCheck {
  static void Call(RobotDesignerForm robot,string name){typeof(RobotDesignerForm).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(robot,null);}
  static void Select(RobotDesignerForm robot,RobotJoint joint){typeof(RobotDesignerForm).GetField("selectedJoint",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(robot,joint.Id);}
  static string specFolder;static int specCount;
  static bool Generate(CADKernel kernel,RobotDocument doc,RobotJoint joint,StringBuilder report){try{var dump=ProceduralBodySpec.Build(doc,joint,joint.BodyGenerator);dump.Remove("PreviousModules");File.WriteAllText(Path.Combine(specFolder,"spec-"+(specCount++)+"-"+joint.Id+".json"),CADDocument.Serializer().Serialize(dump),Encoding.UTF8);report.AppendLine("spec "+(specCount-1)+" "+joint.Name+" mode "+joint.Mode+" reversed "+joint.AxisReversed+" end "+joint.EndX+","+joint.EndY+","+joint.EndZ+" offset "+joint.OffsetX+","+joint.OffsetY+","+joint.OffsetZ);joint.GeneratedBody=ProceduralBodySpec.Generate(kernel,doc,joint,joint.BodyGenerator);var r=joint.GeneratedBody.Result;string design;r.Modules.TryGetValue("design",out design);report.AppendLine((r.GeometryValid?"OK   ":"BAD  ")+joint.Name+" | "+design+" | parts "+r.Parts.Count+" | "+string.Join("; ",r.Issues.Where(i=>i.Status=="error").Select(i=>i.Code+": "+i.Message)));if(!doc.Joints.Any(x=>x.ParentId==joint.Id)){var end=(double[])dump["End"];var direction=new Vector3D(end[0],end[1],end[2]);direction.Normalize();var port=r.Mates.Single(x=>x.Id=="tool_mount");var delta=new Vector3D(port.Origin[0]-end[0],port.Origin[1]-end[1],port.Origin[2]-end[2]);if(Vector3D.CrossProduct(delta,direction).Length>1e-6){report.AppendLine("FAIL tool flange leaves requested end axis");return false;}}return r.GeometryValid;}catch(Exception ex){report.AppendLine("FAIL "+joint.Name+" | "+ex.GetBaseException().Message);return false;}}
  static bool View(RobotDocument doc,string file,StringBuilder report){try{var build=RobotCad.Build(doc);if(!build.Model.Valid||RobotConnections.Validate(build).Count!=0)throw new Exception("Invalid assembly or unmatched flanges");report.AppendLine("assembly valid "+build.Model.Valid+" | connection issues "+RobotConnections.Validate(build).Count);using(var scene=new WpfScene()){foreach(var entry in build.Entries.Values.Where(e=>e.Guide))scene.Hidden.Add(entry.Id);scene.SetResult(new Result{P=new Parameters{Kind=9},Model=build.Model,Robot=build},false);scene.Camera.Yaw=225*Math.PI/180;scene.Camera.Pitch=20*Math.PI/180;scene.SavePng(file+"-a.png",1100,1000);scene.Camera.Yaw=135*Math.PI/180;scene.Camera.Pitch=25*Math.PI/180;scene.SavePng(file+"-b.png",1100,1000);}return true;}catch(Exception ex){report.AppendLine("VIEW FAIL "+ex.GetBaseException().Message);return false;}}
  public static int History(string folder){Directory.CreateDirectory(folder);try{string empty=Path.Combine(folder,"history-empty.robot.json");new RobotDocument().Save(empty);using(var robot=new RobotDesignerForm(empty)){robot.SetDocument(RobotDocument.DefaultReference());int count=robot.Document.Joints.Count;var parent=robot.Document.Joints.Last();double length=parent.Length;var end=new Vector3D(parent.EndX,parent.EndY,parent.EndZ);Select(robot,parent);Call(robot,"AddJoint");var added=robot.Document.Joints.Last();var poses=RobotKinematics.Evaluate(robot.Document,0,false);if((poses[added.Id].Origin-poses[parent.Id].Tip).Length>1e-7||Vector3D.CrossProduct(end,new Vector3D(parent.EndX,parent.EndY,parent.EndZ)).Length>1e-7||parent.Length<100)throw new Exception("Wrong extended parent or child origin");Call(robot,"Undo");if(robot.Document.Joints.Count!=count||Math.Abs(robot.Document.Joints.Last().Length-length)>1e-7)throw new Exception("Undo did not restore parent length");Call(robot,"Redo");if(robot.Document.Joints.Count!=count+1||robot.Document.Joints[count-1].Length<100)throw new Exception("Redo lost parent extension");}using(var robot=new RobotDesignerForm(empty)){var d=RobotDocument.DefaultReference();foreach(var j in d.Joints)j.GeneratedBody=null;robot.SetDocument(d);int n=d.Joints.Count;double original=d.Joints.Last().Length;Select(robot,d.Joints.Last());Call(robot,"AddJoint");Call(robot,"AddJoint");Call(robot,"Undo");Call(robot,"Undo");if(robot.Document.Joints.Count!=n||Math.Abs(robot.Document.Joints.Last().Length-original)>1e-7)throw new Exception("Two structural undos must restore the cache-free fixture");Call(robot,"Redo");Call(robot,"Redo");if(robot.Document.Joints.Count!=n+2)throw new Exception("Two structural redos lost added joints");}File.WriteAllText(Path.Combine(folder,"variant-history680-results.txt"),"PASS axial parent extension, exact child origin, direction, undo and redo",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"variant-history680-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
  public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);specFolder=folder;specCount=0;Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(folder,"profile"));var report=new StringBuilder();bool ok=true;var sink=UiMessage.TestSink;var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};UiMessage.TestSink=text=>report.AppendLine("UI: "+text);string empty=Path.Combine(folder,"empty.robot.json");new RobotDocument().Save(empty);
   using(var robot=new RobotDesignerForm(empty))using(var kernel=new CADKernel()){
    report.AppendLine("== РОБОТ1 + 2 звена");var fixture=RobotDocument.DefaultReference();var originalBodies=fixture.Joints.ToDictionary(x=>x.Id,x=>x.GeneratedBody);foreach(var joint in fixture.Joints)joint.GeneratedBody=null;robot.SetDocument(fixture);int before=robot.Document.Joints.Count;double originalLength=robot.Document.Joints.Last().Length;Select(robot,robot.Document.Ordered().Last());for(int i=0;i<2;i++){Call(robot,"AddJoint");var added=robot.Document.Joints.Last();report.AppendLine("added "+added.Name+" blender="+(added.BodyGenerator!=null&&added.BodyGenerator.BlenderDesign));}
    var parent=robot.Document.Joints[before-1];if(parent.Length<100||robot.Document.Joints.Skip(before).Any(x=>new Vector3D(x.OffsetX,x.OffsetY,x.OffsetZ).Length>1e-8))throw new Exception("Axial spacing or zero offsets lost");Call(robot,"Undo");Call(robot,"Undo");if(robot.Document.Joints.Count!=before||Math.Abs(robot.Document.Joints.Last().Length-originalLength)>1e-6)throw new Exception("Undo must restore original short parent");Call(robot,"Redo");Call(robot,"Redo");var doc=robot.Document.Clone();foreach(var joint in doc.Joints.Take(before-1))joint.GeneratedBody=originalBodies[joint.Id];foreach(var joint in doc.Joints.Skip(before-1).Reverse())ok&=Generate(kernel,doc,joint,report);doc.Save(Path.Combine(folder,"robot1-plus2.robot.json"));ok&=View(doc,Path.Combine(folder,"robot1-plus2"),report);
    report.AppendLine("== РОБОТ1 + 1 звено");robot.SetDocument(RobotDocument.DefaultReference());Select(robot,robot.Document.Ordered().Last());Call(robot,"AddJoint");doc=robot.Document.Clone();foreach(var joint in doc.Joints.Skip(before-1).Reverse())ok&=Generate(kernel,doc,joint,report);ok&=View(doc,Path.Combine(folder,"robot1-plus1"),report);
    report.AppendLine("== новый робот, 3 звена");robot.SetDocument(new RobotDocument());for(int i=0;i<3;i++)Call(robot,"AddJoint");doc=robot.Document.Clone();foreach(var joint in doc.Joints.AsEnumerable().Reverse())ok&=Generate(kernel,doc,joint,report);ok&=View(doc,Path.Combine(folder,"new-3"),report);
   }
  }catch(Exception ex){report.AppendLine("ERROR "+ex);ok=false;}finally{UiMessage.TestSink=sink;AppSettings.Current=old;}
  File.WriteAllText(Path.Combine(folder,"variant-check.txt"),report.ToString(),Encoding.UTF8);return ok?0:1;}
 }
}
